float mo_next;
void() MoverObserve =
{
    local entity bot, saved, m;
    if (time < mo_next) return;
    mo_next = time + 0.5;
    saved = self; bot = argus_bots;
    while (bot != world)
    {
        self = bot;
        if (self.health > 0)
        {
            m = Argus_NearestMover (320);
            dprint ("MOVOBS "); dprint (self.netname); dprint (" t "); dprint (ftos (time));
            dprint (" pos "); dprint (vtos (self.origin));
            dprint (" vel "); dprint (vtos (self.velocity));
            dprint (" yaw "); dprint (ftos (self.ar_moveyaw));
            dprint (" node "); dprint (vtos (self.ar_node.origin));
            dprint (" goal "); dprint (self.ar_goal.classname);
            dprint (" lift/wait/jump/rj/sprint "); dprint (ftos (self.ar_hoplift));
            dprint (" "); dprint (ftos (self.ar_liftwait)); dprint (" "); dprint (ftos (self.ar_hopjump));
            dprint (" "); dprint (ftos (self.ar_hoprj)); dprint (" "); dprint (ftos (self.ar_sprintstate));
            dprint (" ground "); dprint (self.groundentity.classname); dprint (" "); dprint (self.groundentity.model);
            dprint (" nearest "); dprint (m.classname); dprint (" "); dprint (m.model);
            dprint (" state "); dprint (ftos (m.state)); dprint (" top "); dprint (ftos (m.absmax_z));
            dprint (" bounds "); dprint (vtos (m.absmin)); dprint (" "); dprint (vtos (m.absmax)); dprint ("\n");
        }
        bot = bot.ar_chain;
    }
    self = saved;
};

mover_task.qc.source:
float mt_started, mt_ended, mt_when;
entity mt_bot, mt_goal;
void() MoverTaskBefore =
{
    local entity b, saved;
    if (mt_started || time < 2) return;
    mt_started = 1; mt_when = time;
    b = argus_bots;
    while (b != world)
    {
        if (b.ar_slot == 0) mt_bot = b;
        else { b.health = 0; b.takedamage = DAMAGE_NO; b.solid = SOLID_NOT;
               b.movetype = MOVETYPE_NONE; b.nextthink = 0; b.think = SUB_Null;
               b.ar_respawntime = time + 3600; }
        b = b.ar_chain;
    }
    saved = self; self = mt_bot; Argus_Nav_Abort (self); Argus_BaseStats ();
    setorigin (self, '625 1425 24'); self.velocity = '0 0 0';
    self.ar_lastpos = self.origin; self.ar_nextstall = time + 2;
    self.ar_enemy = world; self.ar_node = world; self.ar_pending = 1; self.ar_mode = 0;
    self.ar_hoplift = 0; self.ar_hopjump = 0; self.ar_hoprj = 0; self.ar_hoptrain = 0;
    self.ar_hopswim = 0; self.ar_hopdoor = 0; self.ar_sprintstate = 0;
    self.ar_taskstart = time; self.ar_taskdeadline = time + 60;
    mt_goal = spawn (); mt_goal.classname = "argus_task_goal";
    mt_goal.solid = SOLID_TRIGGER; mt_goal.flags = FL_ITEM;
    setsize (mt_goal, '-8 -8 -8', '8 8 8'); setorigin (mt_goal, '433 1297 208');
    self.ar_taskgoal = mt_goal; self.ar_goal = mt_goal; self.ar_goalstart = time + 3600;
    dprint ("MVTASK begin e1m6 lower_to_prize\n"); self = saved;
};
void() MoverTaskAfter =
{
    if (!mt_started || mt_ended) return;
    if (mt_bot.ar_taskgoal == world || time > mt_when + 45 || mt_bot.health <= 0)
    {
        mt_ended = 1;
        dprint ("MVTASK result elapsed "); dprint (ftos (time - mt_when));
        dprint (" completed "); dprint (ftos (mt_bot.ar_taskgoal == world && mt_bot.health > 0));
        dprint (" pos "); dprint (vtos (mt_bot.origin)); dprint ("\n");
    }
};

